//
// Rhode Island income tax withholding: "2026 Rhode Island Employer's Income
// Tax Withholding Tables", Percentage Method (period beginning on or after
// January 1, 2026; one table for all filing statuses):
//   1. one withholding exemption x exemptions claimed on Form RI W-4
//      ($1,000 a year / periods - e.g. $19.23 weekly - but $0 when the
//      period's wages are over $290,800 a year / periods, e.g. $5,592.31
//      weekly)
//   2. subtract from wages
//   3. the period's rate table (3.75% / 4.75% / 5.99%)
// Rate tables generated by tools/state/generate_ri.py from the booklet. The
// booklet's example ($2,195 weekly, 1 exemption -> $87.57) is in the tests,
// and the tests reproduce every printed exemption amount and threshold.
//
// RI W-4 input: { exemptions, additionalWithholdingCents?, exempt? }.
// Employers "can no longer rely on federal withholding exemption
// certificates". No RI W-4 on file: the booklet doesn't say; this uses zero
// exemptions (the higher-withholding choice). Flagged.
//
// Wages: federal income-tax wages; the booklet doesn't address 401(k)
// directly. Rhode Island income starts from federal AGI, which excludes
// pre-tax 401(k) deferrals.

const { formChecker, onFile, PERIOD_BY_COUNT } = require("./formUtil");
const { fromBaseTable } = require("./brackets");

// Generated by tools/state/generate_ri.py (wages paid on or after January 1, 2026).
const RATE_TABLES = Object.freeze({
  daily: Object.freeze([[0, 0, 375], [31558, 1183, 475], [71712, 3090, 599]]),
  weekly: Object.freeze([[0, 0, 375], [157800, 5918, 475], [358600, 15456, 599]]),
  biweekly: Object.freeze([[0, 0, 375], [315600, 11835, 475], [717100, 30906, 599]]),
  semimonthly: Object.freeze([[0, 0, 375], [341900, 12821, 475], [776900, 33484, 599]]),
  monthly: Object.freeze([[0, 0, 375], [683800, 25643, 475], [1553800, 66968, 599]]),
  quarterly: Object.freeze([[0, 0, 375], [2051300, 76924, 475], [4661300, 200899, 599]]),
  semiannual: Object.freeze([[0, 0, 375], [4102500, 153844, 475], [9322500, 401794, 599]]),
  annual: Object.freeze([[0, 0, 375], [8205000, 307688, 475], [18645000, 803588, 599]]),
});

const TABLES = Object.freeze({
  2026: Object.freeze({
    annualExemptionCents: 1_000_00,
    annualExemptionCutoffCents: 290_800_00,
    rateTables: RATE_TABLES,
    sources: Object.freeze([
      "RI Division of Taxation, 2026 Rhode Island Employer's Income Tax Withholding Tables: https://tax.ri.gov/sites/g/files/xkgbur541/files/2025-12/2026%20Withholding%20Tax%20Booklet.pdf",
    ]),
  }),
});

/** Per-period exemption amount and wage cutoff, as printed (annual / periods). */
function exemptionFor(t, payPeriodsPerYear) {
  return {
    amountCents: Math.round(t.annualExemptionCents / payPeriodsPerYear),
    cutoffCents: Math.round(t.annualExemptionCutoffCents / payPeriodsPerYear),
  };
}

function validateForm(form) {
  if (!onFile(form)) return;
  const c = formChecker("Rhode Island RI W-4");
  c.bool(form, "exempt");
  if (form.exempt) return;
  c.nonNegInt(form, "exemptions");
  c.cents(form, "additionalWithholdingCents");
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  if (!period) throw new Error(`Rhode Island has no rate table for ${payPeriodsPerYear} pay periods a year`);
  const has = onFile(form);
  if (has && form.exempt) return { stateCents: 0, formBasis: "ri-w-4-exempt", lines: {} };
  const { amountCents, cutoffCents } = exemptionFor(t, payPeriodsPerYear);
  const each = wagesCents > cutoffCents ? 0 : amountCents;
  const subject = Math.max(0, wagesCents - (has ? form.exemptions ?? 0 : 0) * each);
  const tax = fromBaseTable(subject, t.rateTables[period]);
  const extra = has ? form.additionalWithholdingCents ?? 0 : 0;
  return {
    stateCents: Math.round(tax) + extra,
    formBasis: has ? "ri-w-4" : "none-on-file-zero-exemptions",
    lines: { period, exemptionEachCents: each, subjectCents: subject },
  };
}

module.exports = {
  code: "RI",
  name: "Rhode Island",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  exemptionFor,
  validateForm,
  compute,
};
